from __future__ import annotations


def dashboard_html(site) -> str:
    return f"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{site.company} Analytics</title>
<style>
:root{{--ink:#17201c;--muted:#63706a;--paper:#f3f0e8;--card:#fff;--green:#174d3a;--gold:#c99b45;--line:#dfe4df;--warn:#9a5b10}}
*{{box-sizing:border-box}}body{{margin:0;background:var(--paper);color:var(--ink);font:15px/1.5 system-ui,-apple-system,sans-serif}}
header{{background:var(--green);color:white;padding:1.1rem max(1.2rem,calc((100vw - 1180px)/2));display:flex;justify-content:space-between;align-items:center;gap:1rem}}header h1{{font:600 1.15rem/1.2 Georgia,serif;margin:0}}header small{{opacity:.75}}
main{{max-width:1180px;margin:0 auto;padding:1.5rem}}.toolbar{{display:flex;align-items:center;justify-content:space-between;gap:1rem;margin-bottom:1rem;flex-wrap:wrap}}select,button,input{{font:inherit;border:1px solid var(--line);border-radius:.55rem;background:white;padding:.55rem .75rem}}button{{cursor:pointer;background:var(--green);color:white;border-color:var(--green)}}
.status{{display:flex;gap:.5rem;align-items:center;color:var(--muted)}}.dot{{width:.65rem;height:.65rem;border-radius:50%;background:var(--warn)}}.dot.ok{{background:#26875d}}
.grid{{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1rem}}.card{{background:var(--card);border:1px solid var(--line);border-radius:.85rem;padding:1rem;box-shadow:0 8px 24px #173d2b0a}}.card h2{{font-size:.76rem;text-transform:uppercase;letter-spacing:.08em;color:var(--muted);margin:0 0 .6rem}}.metric{{font:600 1.9rem/1.1 Georgia,serif}}.delta{{font-size:.8rem;color:var(--muted);margin-top:.35rem}}.wide{{grid-column:span 2}}.full{{grid-column:1/-1}}table{{width:100%;border-collapse:collapse}}th,td{{padding:.6rem .35rem;border-bottom:1px solid var(--line);text-align:left}}th{{color:var(--muted);font-size:.75rem;text-transform:uppercase}}.warning{{color:var(--warn)}}.empty{{padding:2rem;text-align:center;color:var(--muted)}}
@media(max-width:850px){{.grid{{grid-template-columns:repeat(2,minmax(0,1fr))}}}}@media(max-width:520px){{.grid{{grid-template-columns:1fr}}.wide{{grid-column:auto}}header{{align-items:flex-start;flex-direction:column}}}}
</style></head><body>
<header><div><h1>Measurement &amp; Reporting Platform</h1><small>{site.company} · {site.canonical_domain}</small></div><small id="updated">Loading stored reporting data…</small></header>
<main><div class="toolbar"><div><label for="period">Reporting period </label><select id="period"><option value="7d">Last 7 days</option><option value="28d" selected>Last 28 days</option><option value="this_month">This month</option><option value="last_month">Last month</option><option value="90d">Last 90 days</option></select></div><div class="status"><span class="dot" id="dot"></span><span id="health">Checking data health</span><button id="refresh">Refresh</button></div></div>
<section class="grid" id="metrics"></section><section class="grid" style="margin-top:1rem"><article class="card wide"><h2>Acquisition</h2><div id="acquisition"></div></article><article class="card wide"><h2>Conversion stages</h2><div id="conversion"></div></article><article class="card wide"><h2>Landing pages</h2><div id="pages"></div></article><article class="card wide"><h2>Expected events</h2><div id="events"></div></article><article class="card wide"><h2>Measurement health</h2><div id="measurement"></div></article><article class="card wide"><h2>Sync status</h2><div id="sync"></div></article></section></main>
<script>
const site={site.site_id!r};const period=document.querySelector('#period');const fmt=new Intl.NumberFormat();
const table=(heads,rows)=>rows.length?`<table><thead><tr>${{heads.map(x=>`<th>${{x}}</th>`).join('')}}</tr></thead><tbody>${{rows.join('')}}</tbody></table>`:'<div class="empty">A successful query returned no rows for this period.</div>';
const get=async path=>{{const r=await fetch(path,{{headers:sessionStorage.apiToken?{{Authorization:'Bearer '+sessionStorage.apiToken}}:{{}}}});if(!r.ok)throw new Error((await r.json()).detail||r.status);return r.json()}};
function metricCard(m){{let change=m.previousValue===null||m.previousValue===undefined?'No comparable value':m.previousValue===0?(m.value===0?'No change':'New activity'):`${{((m.value-m.previousValue)/Math.abs(m.previousValue)*100).toFixed(1)}}% vs prior`;return `<article class="card"><h2>${{m.metric.replaceAll('_',' ')}}</h2><div class="metric">${{m.value===null?'—':typeof m.value==='number'&&m.metric.endsWith('_rate')?(m.value*100).toFixed(1)+'%':fmt.format(m.value)}}</div><div class="delta">${{change}}</div></article>`}}
async function load(){{document.querySelector('#health').textContent='Loading';try{{const p=period.value;const [o,a,c,l,e,h,s]=await Promise.all([get(`/api/companies/company_house_of_dental/overview?period=${{p}}`),get(`/api/websites/${{site}}/acquisition?period=${{p}}`),get(`/api/websites/${{site}}/conversion?period=${{p}}`),get(`/api/websites/${{site}}/landing-pages?period=${{p}}`),get(`/api/websites/${{site}}/events?period=${{p}}`),get(`/api/websites/${{site}}/measurement-health?period=${{p}}`),get(`/api/websites/${{site}}/sync-status`)]);document.querySelector('#metrics').innerHTML=o.metrics.map(metricCard).join('');document.querySelector('#acquisition').innerHTML=table(['Channel','Sessions','Users','Trend','Approved conversions'],a.rows.map(r=>`<tr><td>${{r.channel}}</td><td>${{fmt.format(r.sessions)}}</td><td>${{fmt.format(r.activeUsers)}}</td><td>${{r.sessionChange>=0?'+':''}}${{fmt.format(r.sessionChange)}}</td><td>${{r.approvedConversions??'Pending approval'}}</td></tr>`));document.querySelector('#conversion').innerHTML=table(['Stage','Count'],c.funnel.map(r=>`<tr><td>${{r.stage.replaceAll('_',' ')}}</td><td>${{fmt.format(r.value)}}</td></tr>`));document.querySelector('#pages').innerHTML=table(['Page','Sessions','Users','Events','Approved conversions'],l.rows.slice(0,10).map(r=>`<tr><td>${{r.landingPage}}</td><td>${{fmt.format(r.sessions)}}</td><td>${{fmt.format(r.activeUsers)}}</td><td>${{fmt.format(r.eventCount)}}</td><td>${{r.approvedConversions??'Pending approval'}}</td></tr>`));document.querySelector('#events').innerHTML=table(['Event','Count','Trend','Status'],e.expectedEvents.map(r=>`<tr><td>${{r.event}}</td><td>${{fmt.format(r.count)}}</td><td>${{r.trend>=0?'+':''}}${{fmt.format(r.trend)}}</td><td class="${{r.state==='present'?'':'warning'}}">${{r.state.replaceAll('_',' ')}}</td></tr>`));document.querySelector('#measurement').innerHTML=`<p><strong>${{h.contract.slug}} v${{h.contract.version}}</strong> · <span class="warning">${{h.contract.approvalStatus.replaceAll('_',' ')}}</span></p>`+table(['Check','State'],h.checks.map(r=>`<tr><td>${{r.key.replaceAll('_',' ')}}</td><td class="${{r.state==='ok'?'':'warning'}}">${{r.detail}}</td></tr>`));document.querySelector('#sync').innerHTML=table(['Control','Value'],[['Last successful sync',s.lastSuccessfulSync?new Date(s.lastSuccessfulSync).toLocaleString():'Never'],['Last complete date',s.lastCompleteDate||'None'],['Current job',s.currentJob?s.currentJob.status:'Idle'],['Failed jobs',fmt.format(s.failedJobs)],['Reconciliation',s.reconciliationState||'None'],['Thresholding',s.thresholding?'Yes':'No'],['Dimension data loss',s.dimensionDataLoss?'Yes':'No']].map(r=>`<tr><td>${{r[0]}}</td><td>${{r[1]}}</td></tr>`));document.querySelector('#health').textContent=`${{s.status}} · ${{s.freshness||'no freshness'}}`;document.querySelector('#dot').className='dot '+(s.status==='ok'?'ok':'');document.querySelector('#updated').textContent=s.lastSuccessfulSync?'Stored sync '+new Date(s.lastSuccessfulSync).toLocaleString():'No successful stored sync';}}catch(e){{document.querySelector('#metrics').innerHTML=`<article class="card full empty">Reporting data is not available yet: ${{e.message}}</article>`;document.querySelector('#health').textContent='Data unavailable';document.querySelector('#updated').textContent='Sync required';}}}}
period.addEventListener('change',load);document.querySelector('#refresh').addEventListener('click',load);load();
</script></body></html>"""
